//! One line of a poll cycle, and what a reading adds to its port.

use std::collections::BTreeMap;
use std::ops::Bound::{Excluded, Unbounded};

/// The four fields of a line `PORT BOOT UPTIME OCTETS`, split at single
/// spaces; None without exactly four fields.
pub fn fields(line: &str) -> Option<[&str; 4]> {
    let fields: Vec<&str> = line.split(' ').collect();
    let [port, boot, uptime, octets] = fields[..] else {
        return None;
    };
    Some([port, boot, uptime, octets])
}

/// A decimal number of ASCII digits that fits in `bits` bits (at most 64);
/// None for anything else, a sign included.
pub fn decimal(text: &str, bits: u32) -> Option<u64> {
    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    let value: u64 = text.parse().ok()?;
    if value > mask(bits) {
        return None;
    }
    Some(value)
}

/// The largest value a counter of `bits` bits holds.
fn mask(bits: u32) -> u64 {
    if bits >= 64 {
        u64::MAX
    } else {
        (1u64 << bits) - 1
    }
}

/// One accepted reading of a port.
#[derive(Clone, Copy)]
pub struct Reading {
    pub boot: u32,
    pub uptime: u32,
    pub octets: u64,
    /// The width of the port's counter in this boot.
    pub width: u32,
}

/// What the later of two readings next to each other in time adds: the
/// whole counter after a restart, else what the counter moved, with at most
/// one wrap.
fn step(earlier: &Reading, later: &Reading) -> u64 {
    if earlier.boot != later.boot {
        later.octets
    } else {
        later.octets.wrapping_sub(earlier.octets) & mask(later.width)
    }
}

/// Every reading that arrived, per port. A port's total depends only on the
/// set of its readings: ordered by boot and uptime, the earliest is the
/// baseline and each other one adds `step` from the reading before it.
#[derive(Default)]
pub struct Register {
    readings: BTreeMap<String, BTreeMap<(u32, u32), Reading>>,
}

impl Register {
    /// Records `reading` of `port` and returns the octets it adds, per boot
    /// whose readings count them. A reading already known adds nothing.
    pub fn observe(&mut self, port: &str, reading: Reading) -> Vec<(u32, u64)> {
        let readings = self.readings.entry(port.to_string()).or_default();
        let key = (reading.boot, reading.uptime);
        if readings.contains_key(&key) {
            return Vec::new();
        }
        let before = readings.range(..key).next_back().map(|(_, r)| *r);
        let after = readings.range((Excluded(key), Unbounded)).next().map(|(_, r)| *r);
        let mut change: BTreeMap<u32, i128> = BTreeMap::new();
        if let Some(before) = &before {
            *change.entry(reading.boot).or_default() += i128::from(step(before, &reading));
        }
        if let Some(after) = &after {
            let entry = change.entry(after.boot).or_default();
            *entry += i128::from(step(&reading, after));
            if let Some(before) = &before {
                *entry -= i128::from(step(before, after));
            }
        }
        readings.insert(key, reading);
        change
            .into_iter()
            .filter(|(_, octets)| *octets > 0)
            .map(|(boot, octets)| (boot, u64::try_from(octets).unwrap_or(u64::MAX)))
            .collect()
    }
}

//! The octets of each customer in the current period, and its frame.

use std::collections::BTreeMap;

#[derive(Default)]
pub struct Usage {
    octets: BTreeMap<u16, u64>,
}

impl Usage {
    /// Adds `octets` to the customer and returns its new usage.
    pub fn add(&mut self, customer: u16, octets: u64) -> u64 {
        let used = self.octets.entry(customer).or_insert(0);
        *used = used.saturating_add(octets);
        *used
    }

    pub fn of(&self, customer: u16) -> u64 {
        self.octets.get(&customer).copied().unwrap_or(0)
    }

    /// The period's frame; a new period starts.
    pub fn close(&mut self) -> Vec<u8> {
        let records: Vec<_> = self.octets.iter().filter(|(_, used)| **used > 0).collect();
        let mut out = b"PT1\0".to_vec();
        out.extend_from_slice(&(records.len() as u16).to_le_bytes());
        for (customer, used) in records {
            let kib = u32::try_from(used.div_ceil(1024)).unwrap_or(u32::MAX);
            out.extend_from_slice(&customer.to_le_bytes());
            out.extend_from_slice(&kib.to_le_bytes());
        }
        self.octets.clear();
        out
    }
}

//! The meter: its configuration, poll cycles and the current period.

use std::collections::{BTreeMap, BTreeSet};

use super::billing::Usage;
use super::counter::{decimal, fields, Reading, Register};

/// The quota written for a customer on a flat rate, which has no quota.
const FLAT_RATE: u64 = 4_294_967_295;

#[derive(Clone, Copy)]
struct Port {
    width: u32,
    owner: u16,
}

#[derive(Debug, PartialEq)]
pub struct Alert {
    pub customer: u16,
    pub used: u64,
}

#[derive(Debug, Default, PartialEq)]
pub struct Receipt {
    pub rejected: Vec<usize>,
    pub alerts: Vec<Alert>,
}

#[derive(Default)]
pub struct Meter {
    /// The quota of each customer that has one.
    quotas: BTreeMap<u16, u64>,
    /// Per port, its entries by the boot from which each holds.
    ports: BTreeMap<String, BTreeMap<u32, Port>>,
    tracker: Register,
    usage: Usage,
    alerted: BTreeSet<u16>,
}

impl Meter {
    /// A meter for the text of a configuration file.
    pub fn new(config: &str) -> Meter {
        let mut meter = Meter::default();
        for line in config.lines() {
            let line = line.split('#').next().unwrap_or("");
            let fields: Vec<&str> = line.split_whitespace().collect();
            match fields[..] {
                ["customer", id, quota] => {
                    let (Some(id), Some(quota)) = (decimal(id, 16), decimal(quota, 64)) else {
                        continue;
                    };
                    let id = id as u16;
                    if quota == FLAT_RATE {
                        meter.quotas.remove(&id);
                    } else {
                        meter.quotas.insert(id, quota);
                    }
                }
                ["port", name, width, owner] => meter.add_port(name, width, owner, "0"),
                ["port", name, width, owner, from] => meter.add_port(name, width, owner, from),
                _ => {}
            }
        }
        meter
    }

    fn add_port(&mut self, name: &str, width: &str, owner: &str, from: &str) {
        let (Some(width), Some(owner), Some(from)) =
            (decimal(width, 32), decimal(owner, 16), decimal(from, 32))
        else {
            return;
        };
        if width != 32 && width != 64 {
            return;
        }
        let port = Port {
            width: width as u32,
            owner: owner as u16,
        };
        self.ports
            .entry(name.to_string())
            .or_default()
            .insert(from as u32, port);
    }

    /// The entry of `port` that holds in `boot`.
    fn entry(&self, port: &str, boot: u32) -> Option<Port> {
        let entries = self.ports.get(port)?;
        entries.range(..=boot).next_back().map(|(_, port)| *port)
    }

    /// The reading a line holds, or None for a line that is rejected.
    fn read(&self, line: &str) -> Option<(String, Reading)> {
        let [port, boot, uptime, octets] = fields(line)?;
        let boot = decimal(boot, 32)? as u32;
        let uptime = decimal(uptime, 32)? as u32;
        let entry = self.entry(port, boot)?;
        let octets = decimal(octets, entry.width)?;
        let reading = Reading {
            boot,
            uptime,
            octets,
            width: entry.width,
        };
        Some((port.to_string(), reading))
    }

    /// Takes one poll cycle.
    pub fn consume(&mut self, cycle: &str) -> Receipt {
        let mut receipt = Receipt::default();
        for (index, line) in cycle.lines().enumerate() {
            let Some((port, reading)) = self.read(line) else {
                receipt.rejected.push(index + 1);
                continue;
            };
            let mut added: BTreeMap<u16, u64> = BTreeMap::new();
            for (boot, octets) in self.tracker.observe(&port, reading) {
                if let Some(entry) = self.entry(&port, boot) {
                    let sum = added.entry(entry.owner).or_insert(0);
                    *sum = sum.saturating_add(octets);
                }
            }
            for (customer, octets) in added {
                let used = self.usage.add(customer, octets);
                let over = match self.quotas.get(&customer) {
                    Some(quota) => used > *quota,
                    None => false,
                };
                if over && self.alerted.insert(customer) {
                    receipt.alerts.push(Alert { customer, used });
                }
            }
        }
        receipt
    }

    /// The customer's octets in the current period.
    pub fn usage(&self, customer: u16) -> u64 {
        self.usage.of(customer)
    }

    /// Ends the period: its frame, and a new period starts.
    pub fn roll_period(&mut self) -> Vec<u8> {
        self.alerted.clear();
        self.usage.close()
    }
}
